"""Generated by solo-to-scale; edit `templates/tools/build_portfolio.py` in the plugin, then run upgrade.

The portfolio: several ventures side by side, each in its own repo, on one overview page (Overview, Needs you,
Activity, Costs). founder/portfolio.json lists the ventures. Each venture's dashboard workflow keeps a short
summary as its `dashboard-data` workflow artifact (counts, approvals waiting, recent activity, spend; never the
business documents); this tool reads the newest one from each repo. It never runs a venture's code.

  python tools/build_portfolio.py enabled [--github-output FILE]  # is a portfolio set up here? (CI)
  python tools/build_portfolio.py build [--out DIR] [--offline]   # DIR/index.html (default .portfolio/)
  python tools/build_portfolio.py guard [--github-output FILE]    # may this build be deployed? (CI)
  python tools/build_portfolio.py verify                          # after a deploy: is it behind the login? (CI)

Reading other repos uses the PORTFOLIO_TOKEN environment variable when it is set (a fine-grained token with
read-only Actions access to the venture repos), otherwise gh's own login. A venture that can't be read is
still listed, with the reason. `guard` and `verify` are the dashboard's: deploy only behind a Cloudflare
Access login, and fail if an anonymous visitor gets the page. Python 3 standard library plus the gh CLI.
"""
from __future__ import annotations

import argparse
import datetime as dt
import html
import io
import json
import os
import re
import subprocess
import sys
import zipfile
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402
import build_dashboard as bd  # noqa: E402

PAGE = Path(__file__).resolve().parent / "portfolio.html"
MARKER = 'name="s2s-portfolio"'
ARTIFACT = "dashboard-data"
REPO = re.compile(r"^[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})/[A-Za-z0-9._-]{1,100}$")
MAX_ZIP = 5_000_000
MAX_SUMMARY = 2_000_000
SECTION = "The portfolio"


def settings(root: Path) -> dict[str, Any]:
    try:
        data = json.loads(s.read(root / "founder" / "portfolio.json") or "{}")
    except ValueError:
        data = {}
    return data if isinstance(data, dict) else {}


def ventures(cfg: dict[str, Any]) -> list[dict[str, str]]:
    """The listed ventures, each {"repo", "dashboard"}, de-duplicated; malformed entries are kept with an error."""
    out, seen = [], set()
    for v in cfg.get("ventures") or []:
        v = {"repo": v} if isinstance(v, str) else v if isinstance(v, dict) else {}
        repo = str(v.get("repo") or "").strip()
        if repo.lower() in seen:
            continue
        seen.add(repo.lower())
        out.append({"repo": repo, "dashboard": https(v.get("dashboard"))})
    return out


def https(url: Any) -> str:
    url = str(url or "").strip()
    return url if re.fullmatch(r"https://[^\s\"'<>]+", url) else ""


def enabled(cfg: dict[str, Any]) -> bool:
    return bool(ventures(cfg))


# --- reading each venture's summary ------------------------------------------------------------------------

def gh_bytes(path: str) -> bytes:
    """`gh api path` as raw bytes, with PORTFOLIO_TOKEN as the token when it is set."""
    env = dict(os.environ)
    if env.get("PORTFOLIO_TOKEN"):
        env["GH_TOKEN"] = env["PORTFOLIO_TOKEN"]
    return subprocess.run(["gh", "api", path], capture_output=True, check=True, env=env, timeout=120).stdout


def unpack(blob: bytes) -> dict[str, Any]:
    if len(blob) > MAX_ZIP:
        raise ValueError("artifact too large")
    with zipfile.ZipFile(io.BytesIO(blob)) as z:
        info = z.getinfo("summary.json")
        if info.file_size > MAX_SUMMARY:
            raise ValueError("summary too large")
        data = json.loads(z.read(info).decode("utf-8"))
    if not isinstance(data, dict) or data.get("schema") != bd.SUMMARY_SCHEMA:
        raise ValueError("not a summary this version understands")
    return data


def fetch(repo: str) -> dict[str, Any]:
    """The newest unexpired dashboard summary of one venture, or {"ok": False, "why": ...}."""
    if not REPO.match(repo):
        return {"ok": False, "why": "not a repo name like owner/name"}
    try:
        listing = json.loads(gh_bytes(f"repos/{repo}/actions/artifacts?name={ARTIFACT}&per_page=10") or b"{}")
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired, FileNotFoundError, ValueError):
        return {"ok": False, "why": "can't read the repo: check that PORTFOLIO_TOKEN has read-only Actions access to it"}
    arts = [a for a in (listing.get("artifacts") or []) if isinstance(a, dict) and not a.get("expired")]
    arts.sort(key=lambda a: str(a.get("created_at") or ""), reverse=True)
    if not arts:
        return {"ok": False, "why": "no dashboard summary yet: upgrade the venture to solo-to-scale 1.5.0 or later, "
                                    "and let its dashboard workflow run once"}
    try:
        data = unpack(gh_bytes(f"repos/{repo}/actions/artifacts/{int(arts[0]['id'])}/zip"))
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired, FileNotFoundError, KeyError, TypeError,
            ValueError, zipfile.BadZipFile) as exc:
        return {"ok": False, "why": f"its newest summary can't be read ({type(exc).__name__})"}
    return {"ok": True, "summary": data}


def age_hours(built: str, now: dt.datetime) -> float | None:
    try:
        t = dt.datetime.strptime(built, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=dt.timezone.utc)
    except (TypeError, ValueError):
        return None
    return round((now - t).total_seconds() / 3600, 1)


def build(root: Path, offline: bool = False, now: dt.datetime | None = None) -> dict[str, Any]:
    now = now or dt.datetime.now(dt.timezone.utc)
    cfg = settings(root)
    stale = float(cfg.get("stale_hours") or 3)
    rows: list[dict[str, Any]] = []
    if cfg.get("include_this_repo", True):
        here = bd.summary(bd.build(root, offline, now))
        host = bd.targets(bd.settings(root))[0]
        rows.append({"repo": here["project"].get("repo") or "this repo", "dashboard": f"https://{host}/" if bd.HOST.match(host) else "",
                     "here": True, "ok": True, "summary": here})
    for v in ventures(cfg):
        got = {"ok": False, "why": "built offline"} if offline else fetch(v["repo"])
        rows.append({**v, "here": False, **got})
    for r in rows:
        if r.get("ok"):
            r["age_hours"] = age_hours(r["summary"].get("built", ""), now)
            r["stale"] = r["age_hours"] is None or r["age_hours"] > stale
    return {"built": now.strftime("%Y-%m-%dT%H:%M:%SZ"), "month": now.strftime("%Y-%m"), "stale_hours": stale,
            "ventures": rows}


def page(data: dict[str, Any]) -> str:
    before, _, after = s.read(PAGE).partition("__S2S_DATA__")
    return before.replace("__S2S_TITLE__", html.escape("Portfolio")) + bd.embed(data) + after


# --- commands ----------------------------------------------------------------------------------------------

def cmd_enabled(a: argparse.Namespace) -> int:
    on = enabled(settings(a.root))
    print("portfolio: " + ("set up" if on else "not set up (founder/portfolio.json lists no ventures)"))
    if a.github_output:
        with open(a.github_output, "a", encoding="utf-8") as f:
            f.write(f"enabled={'yes' if on else 'no'}\n")
    return 0


def cmd_build(a: argparse.Namespace) -> int:
    data = build(a.root, a.offline)
    out = a.out or a.root / ".portfolio"
    out.mkdir(parents=True, exist_ok=True)
    (out / "index.html").write_text(page(data), encoding="utf-8", newline="\n")
    (out / "robots.txt").write_text("User-agent: *\nDisallow: /\n", encoding="utf-8", newline="\n")
    bad = [f"{r['repo'] or '(no repo)'}: {r['why']}" for r in data["ventures"] if not r.get("ok")]
    print(f"wrote {out / 'index.html'}: {len(data['ventures'])} ventures"
          + ("; missing:\n  " + "\n  ".join(bad) if bad else ""))
    return 0


def cmd_guard(a: argparse.Namespace) -> int:
    return bd.guard(settings(a.root), a.github_output, "founder/portfolio.json", "portfolio", SECTION)


def cmd_verify(a: argparse.Namespace) -> int:
    return bd.verify(settings(a.root), MARKER, "portfolio")


def main(argv: list[str] | None = None) -> int:
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--root", type=Path, default=s.ROOT, help=argparse.SUPPRESS)
    ap = argparse.ArgumentParser(description="The portfolio overview")
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("enabled", parents=[common]).add_argument("--github-output", default="")
    b = sub.add_parser("build", parents=[common])
    b.add_argument("--out", type=Path)
    b.add_argument("--offline", action="store_true", help="skip GitHub")
    sub.add_parser("guard", parents=[common]).add_argument("--github-output", default="")
    sub.add_parser("verify", parents=[common])
    a = ap.parse_args(argv)
    return {"enabled": cmd_enabled, "build": cmd_build, "guard": cmd_guard, "verify": cmd_verify}[a.cmd](a)


if __name__ == "__main__":
    sys.exit(main())
